mapper.select:
        select
        videoComments.*,
        videos.title,
        videos.cover,
        users.nick_name,
        users.head_img,
        users1.nick_name as nickNameTwo,
        users1.head_img as headImgTwo
        from video_comments videoComments
        left join videos videos on videoComments.video_id = videos.id
		left join users users on videoComments.user_id = users.id
		left join users users1 on videoComments.to_user_id = users1.id

            and videoComments.id = #{id}
            and videoComments.comment_info like concat('%',#{commentInfo},'%')
            and videoComments.user_id = #{userId}
            and videoComments.video_id = #{videoId}
            and videoComments.create_time = #{createTime}
            and videoComments.to_user_id = #{toUserId}
            and videoComments.parent_id = #{parentId}
            and videos.title like concat('%',#{title},'%')
            and videos.cover = #{cover}
            and users.nick_name like concat('%',#{nickName},'%')
            and users.head_img = #{headImg}


            limit #{current},#{pageSize}

        select count(*) from video_comments videoComments
        left join videos videos on videoComments.video_id = videos.id
		left join users users on videoComments.user_id = users.id
        left join users users1 on videoComments.to_user_id = users1.id

            and videoComments.id = #{id}
